import {validateOcrLanguage} from './languages.js';
import {prepareOcr,mapWordBox,rotatePrepared} from './ocr-preprocess.js';
let activeJob=null,scriptPromise=null;
const href=file=>new URL('./vendor/'+file,import.meta.url).href;
async function script(){if(window.Tesseract)return;scriptPromise??=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=href('tesseract.min.js');s.onload=resolve;s.onerror=()=>{scriptPromise=null;reject(Error('تعذر تحميل محرك النصوص. جرّب الإنترنت في الاستخدام الأول.'));};document.head.append(s);});await scriptPromise;}
export function cancelOcr(){if(activeJob){activeJob.cancelled=true;activeJob.reject(Error('تم إلغاء استخراج النص'));activeJob.instance?.terminate().catch(()=>{});}}
function orientationScore(data){
 const words=(data.blocks||[]).flatMap(b=>(b.paragraphs||[]).flatMap(p=>(p.lines||[]).flatMap(l=>l.words||[]))).filter(w=>/[\p{L}\p{N}]/u.test(w.text));
 if(!words.length)return 0;let letters=0,weighted=0;for(const word of words){const n=(word.text.match(/[\p{L}\p{N}]/gu)||[]).length,confidence=Math.max(0,Math.min(100,word.confidence||0))/100,box=word.bbox,horizontal=n<3||!box||box.x1-box.x0>=(box.y1-box.y0)*.8;letters+=n;weighted+=n*confidence*confidence*(horizontal?1:.35);}return weighted/Math.sqrt(Math.max(1,letters));
}
export async function recognize(blob,language='ara+eng',progress=()=>{},options={}){
 let lastProgress=0;const report=(value,status)=>{lastProgress=Math.max(lastProgress,Math.min(1,value));progress(lastProgress,status);};language=validateOcrLanguage(language);const job={cancelled:false,instance:null};const cancelled=new Promise((_,reject)=>{job.reject=reject;});activeJob=job;
 const operation=(async()=>{
  await script();if(job.cancelled)throw Error('تم إلغاء استخراج النص');
  let progressStart=0,progressSpan=.1;report(0,'تجهيز الصورة');const quality=options.quality||'best';let prepared=await prepareOcr(blob,options.preprocess!==false);if(job.cancelled)throw Error('تم إلغاء استخراج النص');let instance=await Tesseract.createWorker(language,1,{workerPath:href('ocr-worker.min.js'),corePath:new URL('./vendor/',import.meta.url).href,langPath:new URL(quality==='fast'?'./vendor/':'./vendor/ocr-best/',import.meta.url).href,cachePath:'waraqa-ocr-'+quality,gzip:true,logger:message=>{if(!job.cancelled)report(progressStart+Math.max(0,Math.min(1,message.progress||0))*progressSpan,message.status);}});
  job.instance=instance;if(job.cancelled){await instance.terminate();throw Error('تم إلغاء استخراج النص');}
  await instance.setParameters({tessedit_pageseg_mode:options.layout||'3',preserve_interword_spaces:'1',user_defined_dpi:'300'});const base=prepared,orientation=options.orientation??'auto',angles=orientation==='auto'?[0,90,180,270]:[Number(orientation)];if(angles.some(a=>![0,90,180,270].includes(a)))throw Error('اتجاه النص غير مدعوم');let data,bestScore=-1;
  for(let i=0;i<angles.length;i++){if(job.cancelled)throw Error('تم إلغاء استخراج النص');progressStart=.1+i*.8/angles.length;progressSpan=.8/angles.length;report(progressStart,'فحص اتجاه النص');const candidate=await rotatePrepared(base,angles[i]);const recognized=await instance.recognize(candidate.blob,{}, {text:true,blocks:true});const score=orientationScore(recognized.data);if(score>bestScore){bestScore=score;data=recognized.data;prepared=candidate;}}
  progressStart=.9;progressSpan=.08;report(.9,'تدقيق النص');
  if(quality==='best'&&language.includes('ara')&&language.includes('eng')){
   const lines=(data.blocks||[]).flatMap(block=>(block.paragraphs||[]).flatMap(paragraph=>paragraph.lines||[]));const candidates=lines.filter(line=>{const text=(line.words||[]).map(w=>w.text).join(' '),arabic=(text.match(/[\u0621-\u064a]/g)||[]).length,latin=(text.match(/[A-Za-z]/g)||[]).length;return arabic>=5&&latin>0&&arabic>latin;});
   if(candidates.length){await instance.terminate();instance=await Tesseract.createWorker('ara',1,{workerPath:href('ocr-worker.min.js'),corePath:new URL('./vendor/',import.meta.url).href,langPath:new URL('./vendor/',import.meta.url).href,cachePath:'waraqa-ocr-fast',gzip:true});job.instance=instance;if(job.cancelled){await instance.terminate();throw Error('تم إلغاء استخراج النص');}await instance.setParameters({tessedit_pageseg_mode:'7',user_defined_dpi:'300'});for(const line of candidates){if(job.cancelled)throw Error('تم إلغاء استخراج النص');const box=line.bbox||{x0:Math.min(...line.words.map(w=>w.bbox.x0)),y0:Math.min(...line.words.map(w=>w.bbox.y0)),x1:Math.max(...line.words.map(w=>w.bbox.x1)),y1:Math.max(...line.words.map(w=>w.bbox.y1))},left=Math.max(0,Math.floor(box.x0)-12),top=Math.max(0,Math.floor(box.y0)-12),width=Math.min(prepared.transform.width-left,Math.ceil(box.x1)-left+12),height=Math.min(prepared.transform.height-top,Math.ceil(box.y1)-top+12);const refined=await instance.recognize(prepared.blob,{rectangle:{left,top,width,height}},{text:true,blocks:true});const replacement=(refined.data.blocks||[]).flatMap(b=>(b.paragraphs||[]).flatMap(p=>(p.lines||[]).flatMap(l=>l.words||[])));const arabicCount=words=>(words.map(w=>w.text).join(' ').match(/[\u0621-\u064a]/g)||[]).length;if(replacement.length>=line.words.length*.7&&arabicCount(replacement)>arabicCount(line.words)){for(const word of replacement){const original=line.words.find(w=>w.confidence>=85&&/^[A-Za-z0-9]+$/.test(w.text)&&Math.abs((w.bbox.x0+w.bbox.x1-word.bbox.x0-word.bbox.x1)/2)<(w.bbox.x1-w.bbox.x0)*.4);if(original){word.text=original.text;word.confidence=original.confidence;}}line.words=replacement;}}}
  }
  const words=[];for(const block of data.blocks||[])for(const paragraph of block.paragraphs||[])for(const line of paragraph.lines||[])for(const word of line.words||[])if(word.text.trim())words.push({text:word.text,bbox:mapWordBox(word.bbox,prepared.transform),confidence:word.confidence});const lines=(data.blocks||[]).flatMap(block=>(block.paragraphs||[]).flatMap(paragraph=>(paragraph.lines||[]).map(line=>(line.words||[]).map(word=>word.text.trim()).filter(Boolean).join(' '))));report(1,'اكتمل استخراج النص');return{text:lines.length?lines.join('\n'):data.text,words,language,confidence:words.length?words.reduce((sum,w)=>sum+w.confidence,0)/words.length:data.confidence,quality,preprocessed:options.preprocess!==false,deskewDegrees:prepared.transform.angle*180/Math.PI,rotationDegrees:prepared.transform.rotationDegrees||0,edited:false};
 })();
 try{return await Promise.race([operation,cancelled]);}finally{if(job.instance)await job.instance.terminate().catch(()=>{});if(activeJob===job)activeJob=null;}
}
